-- Stagepulse world-class command actions: owner unrestricted, others capability-controlled.
create or replace function public.stagepulse_command_action(p_action text,p_entity text,p_id uuid default null,p_payload jsonb default '{}'::jsonb)
returns jsonb language plpgsql security definer set search_path=public,private,auth,pg_temp as $$
declare v_user uuid:=auth.uid(); v_table text; v_perm text; v_result jsonb; v_set text; v_where text;
begin
 if v_user is null then raise exception 'AUTH_REQUIRED'; end if;
 if not private.is_org_owner() then
   v_perm:=case p_action when 'create' then p_entity||'.create' when 'update' then p_entity||'.update' when 'delete' then p_entity||'.delete' when 'approve' then case when p_entity='offers' then 'offers.manage' else 'approvals.manage' end when 'link' then 'resources.manage' else p_entity||'.manage' end;
   if not private.staff_has_exact_perm(v_perm) and not private.staff_has_exact_perm(p_entity||'.manage') then raise exception 'PERMISSION_DENIED'; end if;
 end if;
 if p_action='link' then
   case p_entity
    when 'job_staff' then insert into public.job_staff(job_id,staff_id,fee) values((p_payload->>'job_id')::uuid,(p_payload->>'staff_id')::uuid,coalesce((p_payload->>'fee')::numeric,0)) returning to_jsonb(job_staff) into v_result;
    when 'job_equipment' then insert into public.job_equipment(job_id,equipment_id,quantity,notes) values((p_payload->>'job_id')::uuid,(p_payload->>'equipment_id')::uuid,coalesce((p_payload->>'quantity')::int,1),p_payload->>'notes') returning to_jsonb(job_equipment) into v_result;
    when 'event_resource' then insert into public.event_resources(event_id,resource_type,staff_user_id,equipment_id,vehicle_id,quantity,required,status,notes) values((p_payload->>'event_id')::uuid,p_payload->>'resource_type',nullif(p_payload->>'staff_user_id','')::uuid,nullif(p_payload->>'equipment_id','')::uuid,nullif(p_payload->>'vehicle_id','')::uuid,coalesce((p_payload->>'quantity')::numeric,1),coalesce((p_payload->>'required')::boolean,true),coalesce(p_payload->>'status','planned'),p_payload->>'notes') returning to_jsonb(event_resources) into v_result;
    when 'vehicle_assignment' then insert into public.vehicle_assignments(vehicle_id,event_id,driver_user_id,starts_at,ends_at,status,notes) values((p_payload->>'vehicle_id')::uuid,nullif(p_payload->>'event_id','')::uuid,nullif(p_payload->>'driver_user_id','')::uuid,(p_payload->>'starts_at')::timestamptz,(p_payload->>'ends_at')::timestamptz,coalesce(p_payload->>'status','planned'),p_payload->>'notes') returning to_jsonb(vehicle_assignments) into v_result;
    else raise exception 'LINK_NOT_SUPPORTED'; end case;
 elsif p_action='approve' and p_entity='offers' then
   update public.teklifler set status='accepted',accepted_at=coalesce(accepted_at,now()),updated_at=now() where id=p_id and status in ('new','reviewing','preparing','sent') returning to_jsonb(teklifler) into v_result;
   if v_result is null then raise exception 'OFFER_NOT_FOUND_OR_NOT_APPROVABLE'; end if;
 else
   v_table:=case p_entity when 'company' then 'business_settings' when 'customers' then 'customers' when 'offers' then 'teklifler' when 'jobs' then 'jobs' when 'events' then 'event_projects' when 'staff' then 'staff' when 'equipment' then 'equipment' when 'warehouse' then 'warehouse_locations' when 'vehicles' then 'vehicles' when 'payments' then 'payments' when 'settlements' then 'settlements' when 'business_risks' then 'business_risks' when 'contracts' then 'contracts' when 'suppliers' then 'stagepulse_suppliers' when 'marketing' then 'marketing_campaigns' when 'kpis' then 'executive_kpis' when 'goals' then 'executive_goals' when 'initiatives' then 'strategic_initiatives' when 'ai_tasks' then 'stagepulse_ai_tasks' when 'ai_actions' then 'ai_action_requests' when 'automation' then 'automation_rules' when 'approval_requests' then 'approval_requests' when 'decisions' then 'stagepulse_decisions' when 'app_versions' then 'app_versions' when 'site_media' then 'site_media' else null end;
   if v_table is null then raise exception 'ENTITY_NOT_SUPPORTED'; end if;
   if p_entity='company' and p_action in ('create','delete') then raise exception 'COMPANY_SINGLETON'; end if;
   if p_action='create' then execute format('insert into public.%I select * from jsonb_populate_record(null::public.%I,$1) returning to_jsonb(%I)',v_table,v_table,v_table) into v_result using p_payload;
   elsif p_action='update' then
     if p_id is null then raise exception 'ID_REQUIRED'; end if;
     select string_agg(format('%I=%L',key,value),', ') into v_set from jsonb_each_text(p_payload) where key not in ('id','created_at','updated_at');
     if coalesce(v_set,'')='' then raise exception 'NO_FIELDS'; end if;
     v_where:=case when p_entity='company' then 'id=true' else format('id=%L',p_id) end;
     execute format('update public.%I set %s where %s returning to_jsonb(%I)',v_table,v_set,v_where,v_table) into v_result;
     if v_result is null then raise exception 'NOT_FOUND'; end if;
   elsif p_action='delete' then
     if p_id is null then raise exception 'ID_REQUIRED'; end if;
     execute format('delete from public.%I where id=%L returning jsonb_build_object(''id'',id)',v_table,p_id) into v_result;
     if v_result is null then raise exception 'NOT_FOUND'; end if;
   elsif p_action='approve' then
     if p_entity='approval_requests' then execute 'update public.approval_requests set status=''approved'',approved_by=$1,approved_at=now() where id=$2 and status=''pending'' returning to_jsonb(approval_requests)' into v_result using v_user,p_id;
     elsif p_entity='ai_actions' then execute 'update public.ai_action_requests set status=''approved'',approved_by=$1,approved_at=now() where id=$2 and status=''pending'' returning to_jsonb(ai_action_requests)' into v_result using v_user,p_id;
     else raise exception 'APPROVAL_NOT_SUPPORTED'; end if;
     if v_result is null then raise exception 'APPROVAL_NOT_FOUND_OR_ALREADY_PROCESSED'; end if;
   else raise exception 'ACTION_NOT_SUPPORTED'; end if;
 end if;
 insert into public.stagepulse_audit_log(actor_type,actor_id,action,target_type,target_id,result,metadata) values('user',v_user,p_action,p_entity,coalesce(p_id,(v_result->>'id')::uuid),'success',coalesce(p_payload,'{}'::jsonb));
 return coalesce(v_result,'{}'::jsonb);
exception when others then insert into public.stagepulse_audit_log(actor_type,actor_id,action,target_type,target_id,result,metadata) values('user',v_user,p_action,p_entity,p_id,'failed',jsonb_build_object('error',sqlerrm,'payload',coalesce(p_payload,'{}'::jsonb))); raise;
end $$;
revoke execute on function public.stagepulse_command_action(text,text,uuid,jsonb) from public; grant execute on function public.stagepulse_command_action(text,text,uuid,jsonb) to authenticated;

create or replace function public.stagepulse_command_catalog() returns jsonb language sql security definer stable set search_path=public,private,auth,pg_temp as $$
select jsonb_build_object('modules',jsonb_build_array(
jsonb_build_object('key','company','label','Şirket','actions',jsonb_build_array('view','update')),jsonb_build_object('key','customers','label','Müşteri','actions',jsonb_build_array('view','create','update','delete','report')),jsonb_build_object('key','offers','label','Teklif','actions',jsonb_build_array('view','create','update','delete','approve','report')),jsonb_build_object('key','jobs','label','İş','actions',jsonb_build_array('view','create','update','delete','link','report')),jsonb_build_object('key','events','label','Etkinlik','actions',jsonb_build_array('view','create','update','delete','link','report')),jsonb_build_object('key','staff','label','Personel','actions',jsonb_build_array('view','create','update','delete','link','report')),jsonb_build_object('key','equipment','label','Ekipman','actions',jsonb_build_array('view','create','update','delete','link','report')),jsonb_build_object('key','warehouse','label','Depo','actions',jsonb_build_array('view','create','update','delete','link','report')),jsonb_build_object('key','vehicles','label','Araç','actions',jsonb_build_array('view','create','update','delete','link','report')),jsonb_build_object('key','payments','label','Finans','actions',jsonb_build_array('view','create','update','delete','report')),jsonb_build_object('key','settlements','label','Kârlılık','actions',jsonb_build_array('view','create','update','delete','report')),jsonb_build_object('key','business_risks','label','Risk','actions',jsonb_build_array('view','create','update','delete','report')),jsonb_build_object('key','contracts','label','Sözleşme','actions',jsonb_build_array('view','create','update','delete','report')),jsonb_build_object('key','suppliers','label','Tedarikçi','actions',jsonb_build_array('view','create','update','delete','report')),jsonb_build_object('key','marketing','label','Pazarlama','actions',jsonb_build_array('view','create','update','delete','report')),jsonb_build_object('key','kpis','label','KPI','actions',jsonb_build_array('view','create','update','delete','report')),jsonb_build_object('key','goals','label','Strateji / Hedef','actions',jsonb_build_array('view','create','update','delete','report')),jsonb_build_object('key','initiatives','label','Stratejik Girişim','actions',jsonb_build_array('view','create','update','delete','report')),jsonb_build_object('key','ai_tasks','label','AI','actions',jsonb_build_array('view','create','update','delete','report')),jsonb_build_object('key','automation','label','Otomasyon','actions',jsonb_build_array('view','create','update','delete','report')),jsonb_build_object('key','approval_requests','label','Onay','actions',jsonb_build_array('view','approve','delete','report')),jsonb_build_object('key','decisions','label','Karar / Denetim','actions',jsonb_build_array('view','create','update','delete','report')),jsonb_build_object('key','app_versions','label','APK / Web','actions',jsonb_build_array('view','create','update','delete','report')),jsonb_build_object('key','site_media','label','Web Medya','actions',jsonb_build_array('view','create','update','delete','report')),jsonb_build_object('key','system','label','Sistem Sağlığı','actions',jsonb_build_array('view','report')))); $$;
revoke execute on function public.stagepulse_command_catalog() from public; grant execute on function public.stagepulse_command_catalog() to authenticated;

create or replace function public.stagepulse_audit_row_change() returns trigger language plpgsql security definer set search_path=public,auth,pg_temp as $$ begin insert into public.stagepulse_audit_log(actor_type,actor_id,action,target_type,target_id,result,metadata) values('user',auth.uid(),lower(TG_OP),TG_TABLE_NAME,case when coalesce((case when TG_OP='DELETE' then to_jsonb(OLD)->>'id' else to_jsonb(NEW)->>'id' end),'') ~ '^[0-9a-fA-F-]{36}$' then (case when TG_OP='DELETE' then to_jsonb(OLD)->>'id' else to_jsonb(NEW)->>'id' end)::uuid else null end,'success',jsonb_build_object('old',case when TG_OP='DELETE' then to_jsonb(OLD) else null end,'new',case when TG_OP<>'DELETE' then to_jsonb(NEW) else null end)); return case when TG_OP='DELETE' then OLD else NEW end; end $$;
revoke execute on function public.stagepulse_audit_row_change() from public,authenticated;

do $$ declare t text; begin foreach t in array array['business_settings','customers','teklifler','offer_items','jobs','event_projects','staff','equipment','warehouse_locations','equipment_movements','vehicles','vehicle_assignments','event_resources','payments','settlements','event_financials','business_risks','event_risks','contracts','stagepulse_suppliers','marketing_campaigns','executive_kpis','executive_goals','strategic_initiatives','stagepulse_ai_tasks','ai_action_requests','automation_rules','approval_requests','stagepulse_decisions','app_versions','site_media'] loop execute format('drop trigger if exists trg_stagepulse_audit on public.%I',t); execute format('create trigger trg_stagepulse_audit after insert or update or delete on public.%I for each row execute function public.stagepulse_audit_row_change()',t); end loop; end $$;
